// Resuelve a qué reclutador enrutar la postulación.
//
// El sitio NO envía el correo del reclutador: manda solo el vacanteId —el id
// estable de la columna `id`— y aquí se busca la fila que le corresponde.

const wh = $('📥 Postulación (webhook)').first().json;
const body = wh.body || {};
const cfg = $('⚙️ Configuración').first().json || {};
const filas = $('📋 Leer vacantes').all().map(i => i.json);

// El sitio manda el id estable de la columna `id`. Se busca por ahí y no por
// posición: así reordenar la hoja deja de mandar postulaciones al reclutador
// equivocado.
const buscado = String(body.vacanteId ?? '').trim();
let fila = filas.find(f => String(f.id ?? '').trim() === buscado) || {};

// Compatibilidad: mientras la columna `id` no esté llena —y para enlaces que
// ya andaban circulando— se cae al número de fila, que era el id anterior.
if (!fila.cargo) {
  const idx = parseInt(buscado, 10);
  if (!isNaN(idx) && idx > 0) fila = filas[idx - 1] || {};
}

const limpio = v => String(v ?? '').trim();

// Si la fila no trae correo (o el id no cuadró), va al buzón de revisión.
const reclutador = limpio(fila.correo_reclutador) || cfg.correoFallback;
const enrutadoOk = Boolean(limpio(fila.correo_reclutador));

// Preferimos los datos del Sheet; si algo falta, usamos lo que mandó el sitio.
const cargo  = limpio(fila.cargo)  || limpio(body.cargo)  || '(sin cargo)';
const ciudad = limpio(fila.ciudad) || limpio(body.ciudad) || '(sin ciudad)';
const sector = limpio(fila.sector) || limpio(body.sector) || '';

const autorizaMarketing = limpio(body.autorizaMarketing).toLowerCase() === 'true';

// ¿Vino hoja de vida? El webhook deja los archivos en binary.
const binarios = Object.keys($('📥 Postulación (webhook)').first().binary || {});
const propArchivo = binarios[0] || '';
const tieneHV = binarios.length > 0;

const nombre = limpio(body.nombre);
const documento = `${limpio(body.tipoDocumento) || 'CC'} ${limpio(body.documento)}`.trim();

/* Nombre del archivo en Drive: Nombre_Cargo_Ciudad_Cedula.
   La cédula va al final porque es lo único irrepetible: dos «Auxiliar de
   Cocina» que se llamen igual solo se distinguen por el documento. */
const adjunto = propArchivo
  ? ($('📥 Postulación (webhook)').first().binary || {})[propArchivo]
  : null;

// Drive y Windows no admiten estos caracteres en el nombre de un archivo.
const parte = t => String(t ?? '').replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim();

// Solo los dígitos: el tipo (CC/TI) no aporta nada a un nombre de archivo.
const cedula = limpio(body.documento).replace(/\D/g, '');

/* Sin extensión el archivo queda en Drive sin tipo: no muestra ícono ni abre
   con doble clic. La trae el binario del webhook. */
const extension = adjunto && adjunto.fileExtension
  ? '.' + String(adjunto.fileExtension).replace(/^\./, '')
  : '';

const asunto = `[POSTULACIÓN WEB] ${ciudad} | ${cargo} - ${nombre}`;

const mensaje = [
  'Nueva postulación recibida desde la página web.',
  '',
  `Cargo: ${cargo}`,
  `Ciudad: ${ciudad}`,
  sector ? `Sector: ${sector}` : '',
  '',
  '--- Datos del candidato ---',
  `Nombre: ${nombre}`,
  `Documento: ${documento}`,
  `Edad: ${limpio(body.edad)}`,
  `Teléfono: ${limpio(body.telefono)}`,
  `WhatsApp: ${limpio(body.whatsapp) || '—'}`,
  `Hoja de vida: ${tieneHV ? 'adjunta a este correo' : 'no adjuntó'}`,
  '',
  'Autoriza tratamiento de datos (Ley 1581): sí',
  `Autoriza comunicaciones comerciales: ${autorizaMarketing ? 'sí' : 'no'}`,
  enrutadoOk ? '' : '\n⚠️ No se pudo identificar la vacante en el Sheet: revisar y reenviar al equipo que corresponda.',
].filter(Boolean).join('\n');

return [{
  json: {
    vacanteId: limpio(body.vacanteId),
    reclutador,
    enrutadoOk,
    cargo, ciudad, sector,
    nombre, documento,
    edad: limpio(body.edad),
    telefono: limpio(body.telefono),
    whatsapp: limpio(body.whatsapp),
    autorizaMarketing,
    tieneHV,
    propArchivo,
    nombreArchivo: tieneHV
      ? [parte(nombre), parte(cargo), parte(ciudad), cedula].filter(Boolean).join('_') + extension
      : '',
    asunto,
    mensaje,
    fecha: new Date().toISOString(),
    carpetaDriveHV: cfg.carpetaDriveHV,
    correoCopia: cfg.correoCopia,
  },
  binary: $('📥 Postulación (webhook)').first().binary || {},
}];
